// EXEMPLE ENTIÈREMENT FICTIF. Aucune personne réelle.
return [{json: {
  entreprise: 'Atelier Seine Plomberie (fictif)',
  ville: 'Rouen',
  prenom: 'Camille (fictif)',
  email: 'camille@example.com',
  demande: 'Bonjour, de l eau coule sous mon évier depuis ce matin. Je suis disponible demain après-midi. Pouvez-vous intervenir et me dire ce qu il faut préparer ?',
  canal: 'message de démonstration',
  demo_only: true
}}];

const d=$input.first().json;
if (!d.demo_only || !String(d.email).endsWith('@example.com')) throw new Error('SECURITE: données de démonstration uniquement');
const prompt=[
  'Tu prépares un BROUILLON, jamais une réponse envoyée automatiquement.',
  'Cas: entreprise fictive de plomberie en France.',
  'Identifie le type de demande et un niveau d urgence prudent (indicatif).',
  'Rédige une réponse polie en français au client, 70 à 110 mots.',
  'Ne promets jamais de tarif, délai, diagnostic certain, disponibilité ou rendez-vous.',
  'Si une information manque, demande-la simplement.',
  'Rends EXACTEMENT trois sections: CATEGORIE:, URGENCE:, BROUILLON: .',
  'Entreprise: '+d.entreprise,
  'Ville: '+d.ville,
  'Message fictif: '+d.demande
].join('\\n');
return [{json:{...d,prompt,requires_human_approval:true}}];

const resp=$input.first().json;
const original=$('03 - Préparer instruction FR').first().json;
const message=resp.choices?.[0]?.message?.content;
if (typeof message !== 'string' || !message.trim()) throw new Error('Aucun texte utilisable retourné par Mistral');
return [{json:{
  status:'BROUILLON_NON_ENVOYE',
  source:'Mistral API (appel réel si exécution autorisée)',
  demo_only:true,
  entreprise:original.entreprise,
  destinataire_test:original.email,
  texte_original:original.demande,
  analyse_et_brouillon:message,
  validation_humaine_obligatoire:true,
  autorise_envoi_automatique:false,
  avertissement:'Avant usage réel : vérifier les données, consentements, accès et obligations RGPD.'
}}];
